mapper.select:
SELECT

FROM counterpart_info
WHERE 1=1

    AND company_name LIKE CONCAT('%', #{param.companyName}, '%')


    AND company_code LIKE CONCAT('%', #{param.companyCode}, '%')


    AND legal_representative LIKE CONCAT('%', #{param.legalRepresentative}, '%')


    AND credit_rating = #{param.creditRating}


    AND qualification_level = #{param.qualificationLevel}


    AND blacklist_flag = #{param.blacklistFlag}


    AND registered_capital >= #{param.minRegisteredCapital}


    AND registered_capital <= #{param.maxRegisteredCapital}


    AND address LIKE CONCAT('%', #{param.address}, '%')


    AND contact_person LIKE CONCAT('%', #{param.contactPerson}, '%')


    AND contact_phone LIKE CONCAT('%', #{param.contactPhone}, '%')

ORDER BY create_time DESC

SELECT COUNT(1) > 0
FROM counterpart_info
WHERE company_name = #{companyName}

    AND id != #{excludeId}

SELECT COUNT(1) > 0
FROM counterpart_info
WHERE company_code = #{companyCode}

    AND id != #{excludeId}

SELECT COUNT(*) as totalCount, COUNT(CASE WHEN blacklist_flag = 1 THEN 1 END) as blacklistCount, COUNT(CASE WHEN credit_rating IN ('AAA', 'AA+', 'AA', 'AA-', 'A+', 'A', 'A-') THEN 1 END) as highCreditCount, COUNT(CASE WHEN credit_rating IN ('CCC', 'CC', 'C', 'D') THEN 1 END) as lowCreditCount, COUNT(CASE WHEN registered_capital >= 10000000 THEN 1 END) as largeEnterpriseCount, AVG(registered_capital) as avgRegisteredCapital, MAX(registered_capital) as maxRegisteredCapital, MIN(registered_capital) as minRegisteredCapital FROM counterpart_info WHERE 1=1
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND credit_rating = #{param.creditRating}
AND blacklist_flag = #{param.blacklistFlag}

SELECT credit_rating as creditRating, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM counterpart_info WHERE 1=1
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND blacklist_flag = #{param.blacklistFlag}
), 2) as percentage FROM counterpart_info WHERE credit_rating IS NOT NULL AND credit_rating != ''
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND blacklist_flag = #{param.blacklistFlag}
GROUP BY credit_rating ORDER BY CASE credit_rating WHEN 'AAA' THEN 1 WHEN 'AA+' THEN 2 WHEN 'AA' THEN 3 WHEN 'AA-' THEN 4 WHEN 'A+' THEN 5 WHEN 'A' THEN 6 WHEN 'A-' THEN 7 WHEN 'BBB+' THEN 8 WHEN 'BBB' THEN 9 WHEN 'BBB-' THEN 10 WHEN 'BB+' THEN 11 WHEN 'BB' THEN 12 WHEN 'BB-' THEN 13 WHEN 'B+' THEN 14 WHEN 'B' THEN 15 WHEN 'B-' THEN 16 WHEN 'CCC' THEN 17 WHEN 'CC' THEN 18 WHEN 'C' THEN 19 WHEN 'D' THEN 20 ELSE 21 END

SELECT CASE WHEN registered_capital < 1000000 THEN '100万以下' WHEN registered_capital < 5000000 THEN '100-500万' WHEN registered_capital < 10000000 THEN '500-1000万' WHEN registered_capital < 50000000 THEN '1000-5000万' WHEN registered_capital < 100000000 THEN '5000万-1亿' ELSE '1亿以上' END as capitalRange, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM counterpart_info WHERE registered_capital IS NOT NULL
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND blacklist_flag = #{param.blacklistFlag}
), 2) as percentage FROM counterpart_info WHERE registered_capital IS NOT NULL
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND blacklist_flag = #{param.blacklistFlag}
GROUP BY CASE WHEN registered_capital < 1000000 THEN '100万以下' WHEN registered_capital < 5000000 THEN '100-500万' WHEN registered_capital < 10000000 THEN '500-1000万' WHEN registered_capital < 50000000 THEN '1000-5000万' WHEN registered_capital < 100000000 THEN '5000万-1亿' ELSE '1亿以上' END ORDER BY MIN(registered_capital)

SELECT SUBSTRING_INDEX(SUBSTRING_INDEX(address, '省', 1), '市', 1) as region, COUNT(*) as count, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM counterpart_info WHERE address IS NOT NULL AND address != ''
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND blacklist_flag = #{param.blacklistFlag}
), 2) as percentage FROM counterpart_info WHERE address IS NOT NULL AND address != ''
AND company_name LIKE CONCAT('%', #{param.companyName}, '%')
AND blacklist_flag = #{param.blacklistFlag}
GROUP BY SUBSTRING_INDEX(SUBSTRING_INDEX(address, '省', 1), '市', 1) ORDER BY count DESC LIMIT 20
